import sys
(m, n) = map(int, sys.stdin.readline().split(' '))
land = []
for _ in range(m):
	l = sys.stdin.readline()
	land.append([0 if c == '.' else 1 for c in l])
next_free_below = [[-1] * n for _ in range(m)]
for i in range(n):
	last_free = m - 1
	for j in range(m - 1, -1, -1):
		if land[j][i] == 1:
			last_free = j - 1
		else:
			next_free_below[j][i] = last_free
	next_free_below[m - 1][i] = -1
next_free_right = [[-1] * n for _ in range(m)]
for i in range(m):
	last_free = n - 1
	for j in range(n - 1, -1, -1):
		if land[i][j] == 1:
			last_free = j - 1
		else:
			next_free_right[i][j] = last_free
	next_free_right[i][n - 1] = -1
max_so_far = 0
for i1 in range(m - 1):
	for j1 in range(n - 1):
		if land[i1][j1] == 1:
			continue
		for i2 in range(next_free_below[i1][j1], i1, -1):
			if 2 * (i2 - i1) + 2 * (next_free_right[i1][j1] - j1) < max_so_far:
				continue
			for j2 in range(next_free_right[i1][j1], j1, -1):
				if land[i1][j1] == 0 and land[i2][j2] == 0 and (next_free_below[i1][j1] >= i2) and (next_free_right[i1][j1] >= j2) and (next_free_below[i1][j2] >= i2) and (next_free_right[i2][j1] >= j2):
					max_so_far = max(max_so_far, 2 * (i2 - i1) + 2 * (j2 - j1))
print(max_so_far if max_so_far else 'impossible')
